%% ===========================================================================
%% ANEXO A - CENSO DE PINES, MEDIDO SOBRE EL FUENTE EL 31/08/2026
%%
%% Maestro/include/pines.h y Esclavo/include/pines.h son BYTE-IDENTICOS:
%%     md5 = 8791a4c1f9afbe5e0e55adad2959b3eb   [MEDIDO]
%%
%% El censo es grep de pinMode / digitalRead / digitalWrite sobre src/, no
%% lectura -CLAUDE.md seccion 3.ter-. Las dos puntas declaran EXACTAMENTE los
%% mismos 15 pinMode; lo que NO es simetrico es DONDE viven (ver anexo B).
%%
%% pin   nombre            bornera  estado                          evidencia
%% ----  ----------------  -------  ------------------------------  --------------------------
%% PA0   ROJO1             J3       VIVO   OUTPUT                   semaforo.cpp:49, :193
%% PA1   AMARILLO1         J4       VIVO   OUTPUT                   semaforo.cpp:51, :194
%% PA2   VERDE1            J5       VIVO   OUTPUT                   semaforo.cpp:53, :195
%% PA3   ROJO2             J6       VIVO   OUTPUT                   semaforo.cpp:50, :196
%% PA4   AMARILLO2         J7       VIVO   OUTPUT                   semaforo.cpp:52, :197
%% PA5   VERDE2            J8       VIVO   OUTPUT                   semaforo.cpp:54, :198
%% PA6   ROJO_PEATON       J11      MUERTO declarado, sin uso       pines.h:15 + coment. main.cpp:35
%% PA7   VERDE_PEATON      J9       MUERTO declarado, sin uso       pines.h:16 + coment. main.cpp:35
%% PA8   RS485_IN_DE_RE    U2       VIVO   OUTPUT HIGH              bluetooth.cpp:68-69 / :76-77
%% PA9   RS485_IN_TX       J10      MUERTO declarado, sin uso       solo pines.h:99
%% PA10  RS485_IN_RX       J10      MUERTO declarado, sin uso       solo pines.h:98
