%% PB10  RS485_OUT_TX      J12      VIVO   USART3 - radio LoRa      pines.h:113
%% PB11  RS485_OUT_RX      J12      VIVO   USART3 - radio LoRa      pines.h:112
%% PB12  LORA_DE_RE        J12      VIVO   OUTPUT                   pines.h:19
%% PB13  BOTON2 / MANDO_B  J16 p8   VIVO   INPUT_PULLUP - SE QUEDA  botones.cpp:51, :120
%% PB14  BOTON3 Aceptar    J16 p10  VIVO HOY - SE RETIRA (31/08)    botones.cpp:52, :131
